from itertools import product

fixed = {3:1, 9:0}
triples = [(0,1,4),(0,2,5),(0,3,6),(1,2,7),(1,3,8),(2,3,9),(4,5,7),(4,6,8),(5,6,9),(7,8,9)]

def is_good(coloring):
    for a,b,c in triples:
        if coloring[a] == coloring[b] == coloring[c]:
            return False
    return True

solutions = []
for vals in product([0,1], repeat=10):
    coloring = list(vals)
    if all(coloring[k] == v for k,v in fixed.items()):
        if is_good(coloring):
            solutions.append(coloring)

print(len(solutions))
if solutions:
    print(solutions[0])
